import{_ as t}from"./chunks/theme.DILvgyre.js";import{_ as o,o as a,c,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"도는 세션에 말 걸기","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/barge-in"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/barge-in"}],["meta",{"property":"og:title","content":"도는 세션에 말 걸기"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/barge-in.md","filePath":"docs/barge-in.md"}'),r={name:"docs/barge-in.md"};function n(s,e,i,p,l,m){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="도는-세션에-말-걸기" tabindex="-1">도는 세션에 말 걸기 <a class="header-anchor" href="#도는-세션에-말-걸기" aria-label="Permalink to &quot;도는 세션에 말 걸기&quot;">​</a></h1><p><strong>턴이 끝나기를 기다리지 않으셔도 됩니다.</strong> 티켓 상세의 <a href="/docs/screens">진행 기록</a> 아래 입력칸에 한 줄 넣고 보내면 그 문장이 세션의 stdin으로 들어가고, 세션은 하던 일을 접고 그 말을 따릅니다. stdin은 실행 중인 프로그램이 바깥에서 글을 받는 통로입니다. 워커 화면의 스트림 다이얼로그에도 같은 칸이 있습니다.</p><p><img src="'+t+`" alt="세션 스트림이 도구 호출을 한 줄씩 늘려 가는 동안, 아래 입력창에 문장을 넣고 보내기를 누르자 그 문장이 참견 줄로 스트림에 나타나고 세션이 이어서 방향을 바꿉니다."></p><p>실제 왕복을 찍은 것입니다. 세션이 <code>notes/a.md</code>를 읽은 참에 참견 한 줄이 들어갑니다. &quot;지금 읽은 것까지만 정리하고, summary.md는 한국어 한 줄로 줄여주세요.&quot; 13초 뒤 세션이 남긴 <code>summary.md</code>는 한 줄입니다.</p><ul><li>입구는 세션마다 FIFO 하나입니다. FIFO는 프로그램끼리 글을 주고받으라고 만드는 특수한 파일이고, 먼저 넣은 줄이 먼저 나갑니다. 티켓을 워커에 물리는 디스패처가 티켓을 잡는 순간 만들고, 세션이 끝나면 지웁니다. 이 경로가 티켓 frontmatter의 <code>inbox:</code> 값이고(<a href="/docs/states">티켓이 지나는 상태</a> 참고), 세션이 끝나면 값도 같이 비워집니다.</li><li>스트림의 원본은 claude가 이미 쓰고 있는 트랜스크립트입니다. 화면을 위해 새로 남기는 파일이 없습니다.</li><li><strong>참견은 화면이 지어낸 메아리가 아니라 트랜스크립트에 실제로 남은 줄입니다.</strong> 보낸 문장이 그대로 그 세션의 입력 기록에 들어갑니다.</li><li>창은 세션이 도는 동안만 열려 있습니다. 턴이 끝나면 닫힙니다.</li></ul><p>최초 프롬프트도 이 입구로 들어갑니다. 사람이 나중에 미는 참견과 같은 통로, 같은 모양입니다. 그래서 이 창은 스트리밍 입력을 받는 엔진(기본값 <code>claude -p</code>)에서만 열립니다. 엔진을 <code>codex</code>처럼 argv로 프롬프트를 한 번에 받는 것으로 바꾸면(<a href="/docs/worker">워커</a> §<code>엔진</code> 열 참고) 이 입구 자체가 생기지 않습니다. argv는 프로그램을 띄울 때 이름 뒤에 붙여 넘기는 값이라, 한 번 뜬 뒤에는 말을 더 넣을 자리가 없습니다.</p><h2 id="파일-첨부" tabindex="-1">파일 첨부 <a class="header-anchor" href="#파일-첨부" aria-label="Permalink to &quot;파일 첨부&quot;">​</a></h2><p>입력칸에는 파일도 겁니다. 클립 손잡이로 고르거나 그냥 붙여넣으시면(<code>⌘V</code>) 됩니다. 스크린샷을 찍어 바로 붙이는 것이 이 기능의 주 용도입니다. 고른 순간 올라가고, 화면은 그것을 칩으로 들고 있다가 보낼 때 본문에 합칩니다.</p><p><strong>첨부는 바이트를 실어 보내는 것이 아니라 파일을 놓고 그 경로를 프롬프트에 적는 것입니다.</strong> 이 칸이 보내는 것은 FIFO에 들어가는 한 줄이라 이미지가 들어갈 자리가 없습니다. 대신 받는 쪽이 <code>Read</code>를 가지고 있으므로, 앱은 파일을 세션이 닿는 자리에 놓고 그 절대경로를 프롬프트 끝에 붙입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;사람이 쓴 본문&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>첨부 파일 — 아래 경로를 Read로 읽어라:</span></span>
<span class="line"><span>/Users/…/myproject/.dira/attachments/ab12cd34-screenshot.png</span></span></code></pre></div><ul><li>놓이는 자리는 <code>&lt;큐 루트&gt;/attachments/</code>입니다. 파일명 앞에 8자리 16진수가 붙어서, 같은 이름을 두 번 붙여도 덮어쓰지 않습니다. <strong>자동 삭제는 없습니다.</strong> 티켓 본문과 트랜스크립트가 이 경로를 영구히 참조하므로 지우면 이력이 깨진 링크가 됩니다. 용량 정리는 사람이 합니다.</li><li>상한은 1건 20MB, 한 번에 10개입니다. 넘으면 그 파일만 거절하고 사유가 칩 자리에 남습니다. 종류 제한은 없습니다. <code>Read</code>가 못 여는 형식이면 세션이 그렇게 말합니다.</li><li>파일 내용을 본문 안에 그대로 옮겨 적지 않습니다. 텍스트 파일이라도 경로만 적습니다. 안 그러면 티켓 본문이 로그 한 벌만큼 불어납니다.</li><li>붙는 칸은 넷입니다. 요구 접수, 티켓 발행, 여기(참견·이어받기), 프로젝트 홈 질의. 표기는 넷이 같습니다.</li><li>스크린샷을 두 장 붙이면 칩 둘이 다 <code>image.png</code>입니다. 크롬이 주는 이름이 그것이라 그렇고, 디스크에서는 앞의 8자리가 갈라 줍니다.</li><li>드래그 앤 드롭은 없습니다.</li></ul><h2 id="에이전트가-스스로-거는-잠금" tabindex="-1">에이전트가 스스로 거는 잠금 <a class="header-anchor" href="#에이전트가-스스로-거는-잠금" aria-label="Permalink to &quot;에이전트가 스스로 거는 잠금&quot;">​</a></h2><p><strong>추측으로 진행하는 대신 되묻습니다.</strong> 티켓 본문에 질문을 붙이고 존재하지 않는 파일을 <code>deps</code>로 걸어 아무 워커도 못 집게 만듭니다. 앞에서 본 <code>deps</code>는 아직 안 끝난 티켓을 기다리는 용도였는데(자세한 것은 <a href="/docs/ticket-writing">티켓 직접 발행하기</a>에 있습니다), 여기서는 아예 없는 해시를 건다는 점이 다릅니다. 답을 쓰면 그 파일이 생겨 잠금이 저절로 풀립니다.</p><ul><li>잠긴 티켓은 큐에서 보입니다. 화면에서 답할 수 있다는 뜻입니다.</li><li>사람이 상태를 되돌리지 않습니다. 잠금과 해제가 같은 규칙입니다.</li><li>같은 이유로 죽는 티켓이 세션을 무한히 태우지도 않습니다. 2회까지만 자동 회수하고 3회째는 질문이 됩니다.</li><li>본문 마지막 절이 <code>## 블록</code>이면 횟수와 무관하게 바로 질문이 됩니다. 세션이 벽을 보고 스스로 멈춘 것이라 다시 돌려 봐야 얻는 게 없어서입니다.</li></ul><p>이 네 줄을 실제로 돌리는 것은 <code>reap</code>, 죽은 세션이 남긴 티켓을 거둬들이는 절차입니다. 세션이 죽은 채로 남은 티켓을 발견하면 우선 <code>attempts</code>를 올리며 자동으로 회수해 다시 큐에 돌립니다. 그런데 같은 이유로 두 번 더 죽으면, 즉 3회째부터는 회수 대신 본문에 <code>## 질문 n</code>을 붙이고 아직 없는 해시를 <code>deps</code>(와 <code>awaiting:</code>)에 걸어 열림으로 되돌립니다. <code>attempts</code>와 무관한 지름길도 있습니다. 되돌린 티켓 본문의 마지막 <code>##</code> 절이 <code>## 블록</code>이면 1회째든 2회째든 그 즉시 같은 답변 요청으로 올립니다(<code>tickets.py</code> <code>reclaim</code>, 529-537번째 줄). 답변 파일이 생기기 전에는 <code>deps</code>가 미충족이라 어떤 워커도 그 티켓을 집어 가지 않고, 답이 달리면 <code>attempts</code>는 0에서 다시 셉니다.</p><p>다음은 <a href="/docs/ticket-writing">티켓 직접 발행하기</a>입니다.</p>`,16)])])}const _=o(r,[["render",n]]);export{u as __pageData,_ as default};
